Let $A = \{a_1, a_2, a_3, \dots\}$ and $B = \{b_1, b_2, b_3, \dots\}$ be subsets of $\N$, with their elements listed in the natural ordering of $\N$.
    \begin{itemize}
        \item The upper density of $A$ in $B$ is $\mu_{\text{up}}(A,B) = \limsup_{n \to \infty} \frac{1}{n}|\{A \cap \{b_1, \dots, b_n\}\}|.$
    \item The lower density of $A$ in $B$ is $\mu_{\text{low}}(A,B) = \liminf_{n \to \infty} \frac{1}{n}|\{A \cap \{b_1, \dots, b_n\}\}|\,.$
    \end{itemize}

